import json
import sys


def decode(bits, ebits, fbits):
    """Return (kind, sign, payload).
    kind in {'nan_q','nan_s','inf','finite'}
    payload for finite: (M, E, is_zero) where value = M * 2**E (M signed).
    """
    width = 1 + ebits + fbits
    v = bits & ((1 << width) - 1)
    s = (v >> (ebits + fbits)) & 1
    e = (v >> fbits) & ((1 << ebits) - 1)
    f = v & ((1 << fbits) - 1)
    Eall = (1 << ebits) - 1
    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    if e == Eall:
        if f == 0:
            return ('inf', s, None)
        top = (f >> (fbits - 1)) & 1
        return ('nan_q' if top else 'nan_s', s, None)
    if e == 0:
        # value = (-1)^s * f * 2^(1-bias-fbits), includes signed zero
        M = -f if s else f
        return ('finite', s, (M, 1 - bias - fbits, f == 0))
    M = -(F + f) if s else (F + f)
    return ('finite', s, (M, e - bias - fbits, False))


def round_to_int(P, k, mode):
    """Round P / 2**k to an integer with the given mode."""
    if k <= 0:
        return P << (-k)
    if mode == 'RTZ':
        return (abs(P) >> k) * (1 if P >= 0 else -1)
    if mode == 'RUP':
        return -((-P) >> k)
    if mode == 'RDN':
        return P >> k
    # nearest modes
    floor = P >> k
    rem = P - (floor << k)
    half = 1 << (k - 1)
    if rem < half:
        return floor
    if rem > half:
        return floor + 1
    if mode == 'RNE':
        return floor if (floor % 2 == 0) else floor + 1
    else:  # RNA: ties away from zero
        return floor + 1 if P >= 0 else floor


def cmp_dyadic(a, ea, b, eb):
    """Compare a*2**ea with b*2**eb for a,b >= 0."""
    if ea <= eb:
        aa, bb = a, b << (eb - ea)
    else:
        aa, bb = a << (ea - eb), b
    return (aa > bb) - (aa < bb)


def solve(req):
    ebits = req['ebits']
    fbits = req['fbits']
    mode = req['mode']
    pairs = req['pairs']

    Eall = (1 << ebits) - 1
    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    emin = 1 - bias
    emax = Eall - 1 - bias
    canonical_nan = (Eall << fbits) | (1 << (fbits - 1))

    invalid = False
    has_nan = False
    inf_signs = set()
    finites = []  # (M, E, is_neg_zero)

    for pair in pairs:
        ka = decode(int(pair[0], 16), ebits, fbits)
        kb = decode(int(pair[1], 16), ebits, fbits)
        for k in (ka, kb):
            if k[0] == 'nan_s':
                invalid = True
                has_nan = True
            elif k[0] == 'nan_q':
                has_nan = True
        if ka[0] in ('nan_q', 'nan_s') or kb[0] in ('nan_q', 'nan_s'):
            # contributes no infinite product; cannot be zero*infinity
            continue
        is_inf_a = (ka[0] == 'inf')
        is_inf_b = (kb[0] == 'inf')
        if is_inf_a or is_inf_b:
            other_zero = False
            if is_inf_a and kb[0] == 'finite' and kb[2][2]:
                other_zero = True
            if is_inf_b and ka[0] == 'finite' and ka[2][2]:
                other_zero = True
            if other_zero:
                invalid = True
                continue
            inf_signs.add(ka[1] ^ kb[1])
            continue
        ma, ea, _za = ka[2]
        mb, eb, _zb = kb[2]
        M = ma * mb
        E = ea + eb
        is_neg_zero = (M == 0) and ((ka[1] ^ kb[1]) == 1)
        finites.append((M, E, is_neg_zero))

    if len(inf_signs) > 1:
        invalid = True

    if invalid:
        return {'bits': format(canonical_nan, 'x'), 'flags': ['invalid']}
    if has_nan:
        return {'bits': format(canonical_nan, 'x'), 'flags': []}
    if inf_signs:
        s = next(iter(inf_signs))
        bits = (s << (ebits + fbits)) | (Eall << fbits)
        return {'bits': format(bits, 'x'), 'flags': []}

    if not finites:
        sign = 1 if mode == 'RDN' else 0
        return {'bits': format(sign << (ebits + fbits), 'x'), 'flags': []}

    Emin = min(E for _M, E, _z in finites)
    N = 0
    for M, E, _z in finites:
        N += M << (E - Emin)

    if N == 0:
        if mode == 'RDN':
            sign = 1
        elif all(z for _M, _E, z in finites):
            sign = 1
        else:
            sign = 0
        return {'bits': format(sign << (ebits + fbits), 'x'), 'flags': []}

    s = 1 if N < 0 else 0
    x = abs(N)
    E = Emin
    L = (x.bit_length() - 1) + E
    Q = max(emin - fbits, L - fbits)
    k = Q - E
    if k <= 0:
        m = N << (-k)
    else:
        m = round_to_int(N, k, mode)
    am = abs(m)

    # overflow check: y = am * 2**Q >= 2**(emax+1)
    if am > 0:
        if Q >= emax + 1:
            over = True
        else:
            over = am >= (1 << (emax + 1 - Q))
    else:
        over = False

    if over:
        away = (mode in ('RNE', 'RNA')) or (mode == 'RUP' and s == 0) or (mode == 'RDN' and s == 1)
        if away:
            bits = (s << (ebits + fbits)) | (Eall << fbits)
        else:
            bits = (s << (ebits + fbits)) | ((Eall - 1) << fbits) | (F - 1)
        return {'bits': format(bits, 'x'), 'flags': ['overflow', 'inexact']}

    inexact = cmp_dyadic(am, Q, x, E) != 0
    underflow = inexact and (cmp_dyadic(am, Q, 1, emin) < 0)

    flags = []
    if inexact:
        flags.append('inexact')
    if underflow:
        flags.append('underflow')

    if am == 0:
        bits = s << (ebits + fbits)
        return {'bits': format(bits, 'x'), 'flags': flags}

    Lr = (am.bit_length() - 1) + Q
    if Lr < emin:
        bits = (s << (ebits + fbits)) | am
    else:
        e = Lr + bias
        nbits = am.bit_length()
        shift = fbits - (nbits - 1)
        if shift >= 0:
            S = am << shift
        else:
            S = am >> (-shift)
        f = S - F
        bits = (s << (ebits + fbits)) | (e << fbits) | f
    return {'bits': format(bits, 'x'), 'flags': flags}


def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        out.append(json.dumps(solve(json.loads(line))))
    sys.stdout.write('\n'.join(out))
    if out:
        sys.stdout.write('\n')


if __name__ == '__main__':
    main()
