from fractions import Fraction


def ref_decode(bits, ebits, fbits):
    width = 1 + ebits + fbits
    v = bits & ((1 << width) - 1)
    s = (v >> (ebits + fbits)) & 1
    e = (v >> fbits) & ((1 << ebits) - 1)
    f = v & ((1 << fbits) - 1)
    Eall = (1 << ebits) - 1
    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    if e == Eall:
        if f == 0:
            return ('inf', s, None)
        top = (f >> (fbits - 1)) & 1
        return ('nan_q' if top else 'nan_s', s, None)
    if e == 0:
        return ('finite', s, Fraction(f) * Fraction(2) ** (1 - bias - fbits))
    return ('finite', s, Fraction(F + f) * Fraction(2) ** (e - bias - fbits))


def _floor(t):
    return t.numerator // t.denominator


def ref_round(t, mode, neg):
    fl = _floor(t)
    if t == fl:
        return fl
    if mode == 'RTZ':
        return fl
    if mode == 'RUP':
        return fl if neg else fl + 1
    if mode == 'RDN':
        return fl + 1 if neg else fl
    frac = t - fl
    half = Fraction(1, 2)
    if frac < half:
        return fl
    if frac > half:
        return fl + 1
    if mode == 'RNE':
        return fl if fl % 2 == 0 else fl + 1
    return fl + 1  # RNA tie -> away from zero -> larger magnitude


def ref_solve(req):
    ebits = req['ebits']; fbits = req['fbits']; mode = req['mode']; pairs = req['pairs']
    Eall = (1 << ebits) - 1
    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    emin = 1 - bias
    emax = Eall - 1 - bias
    canonical_nan = (Eall << fbits) | (1 << (fbits - 1))

    invalid = False
    has_nan = False
    inf_signs = set()
    prods = []  # (value, sign)

    for pair in pairs:
        ka = ref_decode(int(pair[0], 16), ebits, fbits)
        kb = ref_decode(int(pair[1], 16), ebits, fbits)
        for k in (ka, kb):
            if k[0] == 'nan_s':
                invalid = True; has_nan = True
            elif k[0] == 'nan_q':
                has_nan = True
        if ka[0] in ('nan_q', 'nan_s') or kb[0] in ('nan_q', 'nan_s'):
            continue
        if ka[0] == 'inf' or kb[0] == 'inf':
            other = kb if ka[0] == 'inf' else ka
            if other[0] == 'finite' and other[2] == 0:
                invalid = True; continue
            inf_signs.add(ka[1] ^ kb[1]); continue
        prods.append((ka[2] * kb[2], ka[1] ^ kb[1]))

    if len(inf_signs) > 1:
        invalid = True
    if invalid:
        return {'bits': format(canonical_nan, 'x'), 'flags': ['invalid']}
    if has_nan:
        return {'bits': format(canonical_nan, 'x'), 'flags': []}
    if inf_signs:
        s = next(iter(inf_signs))
        return {'bits': format((s << (ebits + fbits)) | (Eall << fbits), 'x'), 'flags': []}

    if not prods:
        sign = 1 if mode == 'RDN' else 0
        return {'bits': format(sign << (ebits + fbits), 'x'), 'flags': []}

    S = sum(v for v, _ in prods)
    if S == 0:
        if mode == 'RDN':
            sign = 1
        elif all(v == 0 and sg == 1 for v, sg in prods):
            sign = 1
        else:
            sign = 0
        return {'bits': format(sign << (ebits + fbits), 'x'), 'flags': []}

    s = 1 if S < 0 else 0
    x = abs(S)
    L = x.numerator.bit_length() - x.denominator.bit_length()
    q = Fraction(2) ** max(emin - fbits, L - fbits)
    t = x / q
    m = ref_round(t, mode, s == 1)
    y = m * q

    flags = []
    if y >= Fraction(2) ** (emax + 1):
        away = (mode in ('RNE', 'RNA')) or (mode == 'RUP' and s == 0) or (mode == 'RDN' and s == 1)
        if away:
            bits = (s << (ebits + fbits)) | (Eall << fbits)
        else:
            bits = (s << (ebits + fbits)) | ((Eall - 1) << fbits) | (F - 1)
        return {'bits': format(bits, 'x'), 'flags': ['overflow', 'inexact']}

    inexact = (y != x)
    underflow = inexact and (y < Fraction(2) ** emin)
    if inexact:
        flags.append('inexact')
    if underflow:
        flags.append('underflow')

    if m == 0:
        return {'bits': format(s << (ebits + fbits), 'x'), 'flags': flags}

    # encode
    Lr = y.numerator.bit_length() - y.denominator.bit_length()
    if Lr < emin:
        frac = y / (Fraction(2) ** (1 - bias - fbits))
        f = int(frac)
        bits = (s << (ebits + fbits)) | f
    else:
        e = Lr + bias
        sig = y / (Fraction(2) ** (e - bias - fbits))
        sig = int(sig)
        f = sig - F
        bits = (s << (ebits + fbits)) | (e << fbits) | f
    return {'bits': format(bits, 'x'), 'flags': flags}
