import itertools, random, sys
sys.path.insert(0, '/app')
import main, ref

MODES = ['RNE', 'RNA', 'RTZ', 'RUP', 'RDN']

def norm(d):
    return (d['bits'].lower().lstrip('0') or '0', tuple(sorted(d['flags'])))

def run_case(req):
    got = norm(main.solve(req))
    exp = norm(ref.solve(req))
    if got != exp:
        print("MISMATCH", req)
        print("  got", main.solve(req))
        print("  exp", ref.solve(req))
        return False
    return True

def exhaustive_single(ebits, fbits):
    width = 1 + ebits + fbits
    n = 1 << width
    pats = [format(i, 'x') for i in range(n)]
    bad = 0
    for a in pats:
        for b in pats:
            for mode in MODES:
                req = {'ebits': ebits, 'fbits': fbits, 'mode': mode, 'pairs': [[a, b]]}
                if not run_case(req):
                    bad += 1
                    if bad > 20:
                        return bad
    return bad

def random_multi(seed, trials, emax_bits=11, fmax_bits=52):
    rnd = random.Random(seed)
    bad = 0
    for _ in range(trials):
        ebits = rnd.randint(3, emax_bits)
        fbits = rnd.randint(2, fmax_bits)
        if 1 + ebits + fbits > 64:
            fbits = 64 - 1 - ebits
            if fbits < 2:
                ebits = 3; fbits = 2
        width = 1 + ebits + fbits
        npairs = rnd.randint(0, 6)
        pairs = []
        for _ in range(npairs):
            a = format(rnd.getrandbits(width), 'x')
            b = format(rnd.getrandbits(width), 'x')
            pairs.append([a, b])
        mode = rnd.choice(MODES)
        req = {'ebits': ebits, 'fbits': fbits, 'mode': mode, 'pairs': pairs}
        if not run_case(req):
            bad += 1
            if bad > 20:
                return bad
    return bad

if __name__ == '__main__':
    print("exhaustive single (3,2)...", exhaustive_single(3, 2))
    print("exhaustive single (3,3)...", exhaustive_single(3, 3))
    print("exhaustive single (4,2)...", exhaustive_single(4, 2))
    print("random multi small...", random_multi(1, 3000, emax_bits=5, fmax_bits=6))
    print("random multi big...", random_multi(2, 3000))
    print("random multi full64...", random_multi(3, 2000))
