import main, ref
from fractions import Fraction

MODES=['RNE','RNA','RTZ','RUP','RDN']

def state(req):
    ebits=req['ebits']; fbits=req['fbits']; pairs=req['pairs']
    invalid=False; has_nan=False; inf=set(); prods=[]
    for p in pairs:
        ka=ref.ref_decode(int(p[0],16),ebits,fbits); kb=ref.ref_decode(int(p[1],16),ebits,fbits)
        for k in (ka,kb):
            if k[0]=='nan_s': invalid=True; has_nan=True
            elif k[0]=='nan_q': has_nan=True
        if ka[0] in ('nan_q','nan_s') or kb[0] in ('nan_q','nan_s'): continue
        if ka[0]=='inf' or kb[0]=='inf':
            other=kb if ka[0]=='inf' else ka
            if other[0]=='finite' and other[2]==0: invalid=True; continue
            inf.add(ka[1]^kb[1]); continue
        prods.append((ka[2]*kb[2], ka[1]^kb[1]))
    if len(inf)>1: invalid=True
    if invalid or has_nan or inf: return None
    return sum(v for v,_ in prods)

def expect_overflow(x, s, mode, ebits, fbits):
    Eall=(1<<ebits)-1; bias=(1<<(ebits-1))-1; F=1<<fbits
    emax=Eall-1-bias; emin=1-bias
    maxfin=Fraction(2*F-1)*Fraction(2)**(emax-fbits)
    thr=Fraction(2)**(emax+1)
    away = (mode in ('RNE','RNA')) or (mode=='RUP' and s==0) or (mode=='RDN' and s==1)
    if x>=thr:
        return ('inf' if away else 'maxfin'), {'overflow','inexact'}
    # maxfin < x < thr
    if mode=='RTZ': chosen='maxfin'
    elif mode=='RUP': chosen='maxfin' if s==1 else 'thr'
    elif mode=='RDN': chosen='maxfin' if s==0 else 'thr'
    else:
        # nearest: midpoint between maxfin and thr
        mid=(maxfin+thr)/2
        if x>mid: chosen='thr'
        elif x<mid: chosen='maxfin'
        else: chosen='thr'  # tie -> even (thr significand even)
    if chosen=='thr':
        return ('inf' if away else 'maxfin'), {'overflow','inexact'}
    return 'maxfin', {'inexact'}

def check(req):
    ebits=req['ebits']; fbits=req['fbits']; mode=req['mode']
    Eall=(1<<ebits)-1; bias=(1<<(ebits-1))-1; F=1<<fbits; emax=Eall-1-bias
    maxfin=Fraction(2*F-1)*Fraction(2)**(emax-fbits)
    S=state(req)
    if S is None or S==0: return True
    s=1 if S<0 else 0; x=abs(S)
    if x<=maxfin: return True
    kind,flags=expect_overflow(x,s,mode,ebits,fbits)
    got=main.solve(req)
    if kind=='inf':
        bits=(s<<(ebits+fbits))|(Eall<<fbits)
    else:
        bits=(s<<(ebits+fbits))|((Eall-1)<<fbits)|(F-1)
    if int(got['bits'],16)!=bits or set(got['flags'])!=flags:
        print('OVF MISMATCH',req,'got',got,'exp',format(bits,'x'),flags)
        return False
    return True

bad=0; n=0
for (eb,fb) in [(3,2),(3,3),(4,2),(4,3)]:
    w=1+eb+fb; pats=[format(i,'x') for i in range(1<<w)]
    for a in pats:
        for b in pats:
            for m in MODES:
                req={'ebits':eb,'fbits':fb,'mode':m,'pairs':[[a,b]]}
                n+=1
